def render_pre(*children: Any, **props: Any) -> rx.Component:
    language = props.get("language")

    code_class = rx.cond(
        language == "bash",
        "language-bash",
        rx.cond(
            language == "uv",
            "language-bash",
            rx.cond(
                language == "css",
                "language-css",
                rx.cond(
                    language == "assets/globals.css",
                    "language-css",
                    rx.cond(
                        language == "toml",
                        "language-toml",
                        rx.cond(
                            language == "pyproject.toml",
                            "language-toml",
                            rx.cond(
                                language == "text",
                                "language-text",
                                "language-python",
                            ),
                        ),
                    ),
                ),
            ),
        ),
    )

    return rx.el.div(
        rx.el.div(
            rx.cond(
                language != "python",
                rx.el.div(
                    rx.el.p(
                        language,
                        class_name="text-muted-foreground text-sm font-normal px-[1rem] py-2",
                    ),
                    class_name="w-full border-b border-input/70 flex flex-row items-center justify-between",
                ),
            ),
            rx.el.div(
                rx.el.pre(
                    rx.el.code(
                        *children,
                        style={
                            "white-space": "pre",
                            "color": "var(--foreground)",
                            "font-size": "13px !important",
